// 修复方案1：完全移除shell执行，使用参数化数组
export function findFilesSafe(pattern: string): Promise<string> {
    return new Promise((resolve, reject) => {

        // 1. 使用白名单验证输入
        const validPatternRegex = /^[a-zA-Z0-9_*.\-]+$/
        if (!validPatternRegex.test(pattern)) {
            return reject(new Error('Invalid pattern format'))
        }

        // 2. 使用spawn的数组形式，不使用shell:true
        const process = spawn('find', [
            '/home',
            '-name',
            pattern,  // 作为独立参数传递，不会被shell解析
            '-type',
            'f'
        ], {
            // 移除 shell: true，或显式设置为 false
            shell: false
        })

        let stdout = ''
        let stderr = ''

        process.stdout.on('data', (data) => {
            stdout += data.toString()
        })

        process.stderr.on('data', (data) => {
            stderr += data.toString()
        })

        process.on('close', (code) => {
            if (code === 0) {
                resolve(stdout)
            } else {
                reject(new Error(`Command failed: ${stderr}`))
            }
        })
    })
}

// 修复方案2：如果必须使用shell，必须转义输入
import { exec } from 'child_process'
import shellescape from 'shell-escape'

export function findFilesSafeWithShell(pattern: string): Promise<string> {
    return new Promise((resolve, reject) => {
        // 1. 严格的输入验证
        const allowedPatterns = ['*.txt', '*.log', '*.json', '*.md']
        if (!allowedPatterns.includes(pattern)) {
            return reject(new Error('Pattern not allowed'))
        }

        // 2. 如果范围更大，使用正则验证
        const safePattern = /^[a-zA-Z0-9_*.\-]+$/.test(pattern)
        if (!safePattern) {
            return reject(new Error('Invalid characters'))
        }

        // 3. 使用shell-escape库转义输入
        const escapedPattern = shellescape([pattern]).replace(/'/g, "''")

        // 4. 构造安全的命令
        const command = `find /home -name ${pattern} -type f`

        exec(command, (error, stdout, stderr) => {
            if (error) {
                reject(error)
            } else {
                resolve(stdout)
            }
        })
    })
}
